fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let len = s.len();
    let p = len - (len % 3);
    let mut res = Vec::with_capacity(len);

    // Process the first P elements in triplets
    for i in 0..p {
        match i % 3 {
            0 => {
                // output[i] = input[i + 2]
                res.push(s[i + 2]);
            }
            1 => {
                // output[i] = input[i - 1]
                res.push(s[i - 1]);
            }
            2 => {
                // output[i] = input[i] (unchanged)
                res.push(s[i]);
            }
            _ => unreachable!(),
        }
    }

    // Copy the remainder unchanged
    for i in p..len {
        res.push(s[i]);
    }

    res
}